INSERT INTO `categories` (`id`, `category_id`, `label`, `badge`, `hero_img`, `tagline`, `sort_order`, `is_active`) VALUES
(1, 'new', 'Новинки', NULL, '/assets/hr.webp', 'Свежие кулинарные премьеры кафе «Белоснежка»: авторские горячие блюда и сезонные новинки от нашего шеф-повара', 10, 1),
(2, 'business_lunch', 'Бизнес-Ланч', '12:00–18:00', '/assets/udon_chicken_img.webp', 'Сытные комплексные обеды по будням с 12:00 до 18:00: горячие блюда с салатом или гарниром и соус на выбор по выгодной цене', 20, 1),
(3, 'mangal', 'Мангал и Стейки', 'Хит', '/assets/$n.webp', 'Сочные блюда в мангале, традиционный шашлык, люля-кебабы, стейки и садж на компанию из отборного мяса и рыбы', 30, 1),
(4, 'salads', 'Салаты', NULL, '/assets/Wn.webp', 'Свежие фирменные и классические салаты со свежими овощами, птицей, морепродуктами и авторскими заправками', 40, 1),
(5, 'starters', 'Холодные и горячие закуски', NULL, '/assets/dr.webp', 'Холодные банкетные тарелки, нарезки мясных и рыбных деликатесов, сырные плато, горячие закуски, запечённые роллы и снеки', 50, 1),
(6, 'hot', 'Первые и Вторые блюда', NULL, '/assets/mr.webp', 'Наваристые супы, сытная солянка, домашнее жаркое и сытные горячие блюда от нашего шеф-повара', 60, 1),
(7, 'garnishes', 'Гарниры', NULL, '/assets/ar.webp', 'Аппетитные гарниры из картофеля, овощей и злаков к основным блюдам и шашлыку', 70, 1),
(8, 'bread', 'Хлеб', NULL, '/assets/zr.webp', 'Свежий тонкий кавказский лаваш и ароматная мягкая выпечка кафе', 80, 1),
(9, 'pizza', 'Пицца', NULL, '/assets/vr.webp', 'Горячая фирменная пицца на тонком тесте с хрустящим бортиком, тягучим сыром моцарелла и отборными начинками', 90, 1),
(10, 'sauces', 'Соусы', NULL, '/assets/Er.webp', 'Фирменные и классические соусы от шеф-повара: тар-тар, барбекю, чесночный, сырный, терияки и другие авторские заправки', 100, 1),
(11, 'tea_coffee', 'Чай, Кофе и Мороженое', NULL, '/assets/Gn.webp', 'Традиционные чайные наборы с мёдом и сухофруктами, натуральный кофе, гляссе, горячий шоколад и освежающий пломбир', 110, 1),
(12, 'bar', 'Барная карта и Напитки', NULL, '/assets/Lr.webp', 'Авторские коктейли, шоты, богатый выбор благородных крепких напитков, вин, разливного пива, а также лимонады и соки', 120, 1),
(13, 'banquet_dishes', 'Банкетные блюда', NULL, '/assets/Rr.webp', 'Специальное банкетное меню для праздничных столов, свадеб и юбилеев: праздничные салаты, изысканные закуски и сытные горячие блюда', 130, 1),
(14, 'banquet', 'Банкеты и Торжества', 'до 150 мест', '/assets/zr.webp', 'Полная банкетная сервировка любого торжества до 150 посадочных мест: свадьбы, юбилеи, дни рождения и корпоративы', 140, 1),
(15, 'wishes', 'Карта пожеланий', 'Прейскурант & Правила', '/assets/Jn.webp', 'Прейскурант возмещения инвентаря и правила комфортного отдыха в кафе «Белоснежка»', 150, 1);
INSERT INTO `dishes` (`id`, `category_ref`, `section_id`, `section_title`, `name`, `weight`, `price`, `price_text`, `note`, `description`, `tag`, `img`, `is_available`, `sort_order`) VALUES
(1, 'new', 1, 'Салаты', 'Салат Каприз', '150 г', 450, '450 ₽', 'куриная печень, листья салата, помидоры, апельсин, медово-горчичная заправка, кунжут', NULL, 'Новинка', '/assets/webp/salad_kapriz-BR9xL2wQ.webp', 1, 10),
(2, 'new', 1, 'Салаты', 'Салат Микс', '150 г', 500, '500 ₽', 'отварная свёкла, листья салата, сёмга, апельсин, брынза, медово-горчичная заправка', NULL, 'Новинка', NULL, 1, 20),
(3, 'new', 1, 'Салаты', 'Цезарь с креветками', '150 г', 550, '550 ₽', 'креветки, салатные листья, помидоры, сыр голландский, сухари, соус цезарь', 'Аппетитный салат с обжаренными креветками, свежими листьями салата, спелыми помидорами, голландским сыром и хрустящими сухарями под соусом цезарь.', 'Хит · Новинка', '/assets/webp/salad_caesar_shrimp-B7wK2mN4.webp', 1, 30),
(4, 'new', 2, 'Горячие блюда', 'Курица по-гавайски', '150 г', 500, '500 ₽', NULL, NULL, 'Новинка', '/images/placeholder_dish.svg', 1, 10),
(5, 'new', 2, 'Горячие блюда', 'Курица по-французски', '150 г', 450, '450 ₽', 'куриное филе, спелые помидоры, сыр, репчатый лук, фирменный соус', 'Сочное куриное филе, запечённое со спелыми томатами под аппетитной сырной корочкой и пикантным авторским соусом.', 'Новинка', '/assets/webp/chicken_french-K7rP2wL9.webp', 1, 20),
(6, 'new', 2, 'Горячие блюда', 'Горбуша под овощами', '150 г', 400, '400 ₽', 'филе сочной горбуши, морковь, лук, сладкий перец, сырная корочка, лимон, зелень', 'Нежное и сочное филе горбуши, запечённое под аппетитной овощной подушкой из сладкой моркови, лука и перца под золотистой сырной корочкой. Подаётся с ломтиками лимона и свежей зеленью.', 'Новинка', '/assets/jpg/gorbusha_hot-B8mN2vP4.jpg', 1, 30),
(7, 'new', 2, 'Горячие блюда', 'Свинина с овощами', '150 г', 650, '650 ₽', 'сочная свинина, баклажаны, сладкий перец, спелые томаты, свежая зелень, тонкий лаваш', 'Ароматные кусочки нежной свинины, обжаренные с баклажанами, сочными томатами, сладким перцем и свежей зеленью. Подаются на тонком лаваше в чугунной сковороде.', 'Новинка', '/assets/jpg/pork_vegetables-C8kN2vP4.jpg', 1, 40),
(8, 'new', 2, 'Горячие блюда', 'Свинина в соусе с грибами', '150 г', 630, '630 ₽', 'свиная вырезка, свежие шампиньоны, сливочный соус, лук, зелень', 'Сочные кусочки свинины, обжаренные до золотистого цвета и томленые в густом ароматном сливочно-грибном соусе.', 'Новинка', '/assets/webp/pork_mushroom_sauce-D8mK4vP2.webp', 1, 50),
(9, 'new', 2, 'Горячие блюда', 'Удон с креветками', '150 г', 400, '400 ₽', 'японская пшеничная лапша удон, тигровые креветки, овощи, пряный соус, кунжут', 'Японская пшеничная лапша удон с тигровыми креветками в пряном соусе с овощами и кунжутом.', 'Новинка', '/assets/webp/udon_shrimp-T7mN2vP4.webp', 1, 60),
(10, 'new', 2, 'Горячие блюда', 'Удон с курицей', '150 г', 350, '350 ₽', 'лапша удон ручной работы собственного приготовления, куриное филе, овощи, соус терияки', NULL, 'Новинка', '/assets/webp/udon_chicken-CV9kL3wQ.webp', 1, 70),
(11, 'new', 2, 'Горячие блюда', 'Удон с грибами', '150 г', 350, '350 ₽', 'пшеничная лапша удон, свежие шампиньоны, овощи, ароматный соус, кунжут', NULL, 'Новинка', NULL, 1, 80),
(12, 'new', 2, 'Горячие блюда', 'Жареные пельмени с говядиной', '150 г', 300, '300 ₽', 'сочная рубленая говядина, пряности, хрустящее тесто, соус, огурец', NULL, 'Новинка', '/assets/webp/fried_dumplings_beef-B3kNm9xL.webp', 1, 90),
(13, 'new', 3, 'Гарниры', 'Фасоль стручковая', '150 г', 200, '200 ₽', NULL, NULL, 'Новинка', NULL, 1, 10),
(14, 'new', 4, 'Горячие закуски и снеки', 'Цезарь-ролл запечённый', '150 г', 450, '450 ₽', 'тонкий лаваш, куриное филе, свежие листья салата, помидоры, сыр, соус цезарь', 'Аппетитная горячая закуска: запечённый в тонком лаваше ролл с сочным куриным филе, свежими листьями салата, помидорами, расплавленным сыром и соусом цезарь.', 'Новинка', '/assets/webp/cezar_roll_baked-B8mN2vP4.webp', 1, 10),
(15, 'business_lunch', 1, 'Ланч меню (с 12:00 до 18:00)', 'Удон с курицей и овощным салатом', '220 г', 250, '250 ₽', 'пшеничная лапша удон ручной работы, куриное филе, овощи, соус терияки, свежий овощной салат', 'Сытный ланч: пшеничная лапша удон собственного приготовления с нежным куриным филе в соусе терияки и порция свежего витаминного салата.', NULL, '/assets/webp/udon_chicken-CV9kL3wQ.webp', 1, 10),
(16, 'business_lunch', 1, 'Ланч меню (с 12:00 до 18:00)', 'Жареные пельмени с курицей и овощным салатом', '220 г', 250, '250 ₽', 'домашние пельмени с куриным фаршем, обжаренные до золотистой корочки, свежий овощной салат', 'Сытный ланч: золотистые хрустящие пельмени с начинкой из сочного куриного филе и порция освежающего овощного салата.', NULL, '/assets/webp/fried_dumplings_chicken-K7mN4vP2.webp', 1, 20),
(17, 'business_lunch', 1, 'Ланч меню (с 12:00 до 18:00)', 'Жареные пельмени с говядиной и овощным салатом', '220 г', 250, '250 ₽', 'домашние пельмени с сочной рубленой говядиной и пряностями, обжаренные на сковороде, свежий овощной салат', 'Сытный ланч: хрустящие жареные пельмени с начинкой из отборной говядины со специями и порция свежего овощного салата.', NULL, '/assets/webp/fried_dumplings_beef-B3kNm9xL.webp', 1, 30),
(18, 'business_lunch', 1, 'Ланч меню (с 12:00 до 18:00)', 'Цезарь-ролл с фри', '220 г', 250, '250 ₽', 'тонкий лаваш, куриное филе, листья салата, помидоры, сыр, фирменный соус цезарь, золотистый картофель фри', 'Сытный ланч: аппетитный ролл в тонком лаваше с сочным куриным филе, томатами, сыром и соусом цезарь с порцией хрустящего картофеля фри.', NULL, '/assets/jpg/cezar_roll_fri-C8kN9wM1.jpg', 1, 40),
(19, 'business_lunch', 2, 'Соус на выбор', 'Тар-тар', '30 г', 70, '70 ₽', 'классический соус на майонезной основе с маринованными огурчиками и укропом', 'Нежный пикантный соус тар-тар на кремовой майонезной основе с добавлением хрустящих маринованных огурчиков, свежего укропа и нотки лимонного сока. Идеально подходит к рыбе, морепродуктам и хрустящим закускам.', NULL, '/assets/jpg/sauce_tartar-B8mN2vP4.jpg', 1, 10),
(20, 'business_lunch', 2, 'Соус на выбор', 'Соевый', '30 г', 70, '70 ₽', 'традиционный пикантный соевый соус', NULL, NULL, '/images/placeholder_dish.svg', 1, 20),
(21, 'business_lunch', 2, 'Соус на выбор', 'Кисло-сладкий', '30 г', 70, '70 ₽', 'азиатский кисло-сладкий соус с легкой фруктовой кислинкой', NULL, NULL, '/images/placeholder_dish.svg', 1, 30),
(22, 'business_lunch', 2, 'Соус на выбор', 'Манго-чили', '30 г', 70, '70 ₽', 'экзотический соус со спелым манго и пикантным перцем чили', NULL, NULL, '/images/placeholder_dish.svg', 1, 40),
(23, 'business_lunch', 2, 'Соус на выбор', 'Барбекю', '30 г', 70, '70 ₽', 'дымный соус BBQ с насыщенным пряным вкусом', NULL, NULL, '/images/placeholder_dish.svg', 1, 50),
(24, 'business_lunch', 2, 'Соус на выбор', 'Сырный', '30 г', 70, '70 ₽', 'нежный бархатистый соус на основе отборных сыров', NULL, NULL, '/images/placeholder_dish.svg', 1, 60),
(25, 'business_lunch', 2, 'Соус на выбор', 'Кавказский', '30 г', 70, '70 ₽', 'пряный томатный соус со свежими кавказскими травами и чесноком', 'Ароматный пряный томатный соус со свежей кинзой, базиликом, чесноком и традиционными кавказскими специями. Превосходно дополняет шашлык, люля-кебаб и жареное мясо.', NULL, '/assets/jpg/sauce_caucasian-B8mN2vP4.jpg', 1, 70),
(26, 'business_lunch', 2, 'Соус на выбор', 'Чесночный', '30 г', 70, '70 ₽', 'сливочно-чесночный соус со свежей зеленью', 'Нежный и пикантный сливочно-чесночный соус со свежим укропом и зеленью петрушки. Идеально подходит к мясу, шашлыку и горячим закускам.', NULL, '/assets/jpg/sauce_garlic-B8mN2vP4.jpg', 1, 80),
(27, 'business_lunch', 2, 'Соус на выбор', 'Терияки', '30 г', 70, '70 ₽', 'традиционный японский карамельно-соевый соус', 'Классический японский густой соус терияки с карамельно-соевым вкусом и легким ароматом пряностей. Идеально подчеркивает вкус птицы, мяса, рыбы и блюд вок.', NULL, '/assets/jpg/sauce_teriyaki-B8mN2vP4.jpg', 1, 90),
(28, 'business_lunch', 2, 'Соус на выбор', 'Сладкий чили', '30 г', 70, '70 ₽', 'сладкий тайский соус с легкой остротой перца чили', NULL, NULL, '/images/placeholder_dish.svg', 1, 100),
(29, 'business_lunch', 2, 'Соус на выбор', 'Гранатовый', '30 г', 70, '70 ₽', 'густой кисло-сладкий гранатовый соус наршараб', NULL, NULL, '/images/placeholder_dish.svg', 1, 110),
(30, 'mangal', 1, 'Шашлыки на мангале', 'Шашлык свиной', '100 г', 400, '400 ₽', 'свиная шейка, маринованный лук', NULL, NULL, '/assets/webp/shashlik_pork_platter-5dNhROfv.webp', 1, 10),
(31, 'mangal', 1, 'Шашлыки на мангале', 'Шашлык куриный', '100 г', 350, '350 ₽', 'куриное филе, фирменный маринад', NULL, NULL, '/images/placeholder_dish.svg', 1, 20),
(32, 'mangal', 1, 'Шашлыки на мангале', 'Шашлык из курицы с овощами', '100 г', 350, '350 ₽', 'куриное филе, перец болгарский, лук', NULL, NULL, '/assets/webp/shashlik_chicken_veg-DdafEJp8.webp', 1, 30),
(33, 'mangal', 1, 'Шашлыки на мангале', 'Шашлык из крыльев', '100 г', 300, '300 ₽', 'куриные крылышки, пикантный маринад, тонкий лаваш, свежий огурец, зелёный лук, кунжут', 'Аппетитные куриные крылышки в авторском пикантном маринаде, обжаренные в мангале до хрустящей золотистой корочки. Подаются на тонком лаваше со свежим огурцом, зелёным луком и кунжутом.', NULL, '/assets/webp/shashlik_wings-H7kM9vX1.webp', 1, 40),
(34, 'mangal', 1, 'Шашлыки на мангале', 'Люля кебаб с говядиной', '100 г', 350, '350 ₽', 'рубленая говядина, свежая зелень, лук, пряности', NULL, NULL, '/assets/webp/lyulya_beef-BoUTVr7S.webp', 1, 50),
(35, 'mangal', 1, 'Шашлыки на мангале', 'Люля кебаб куриный', '100 г', 300, '300 ₽', 'рубленое куриное филе, ароматные пряности', NULL, NULL, '/images/placeholder_dish.svg', 1, 60),
(36, 'mangal', 2, 'Стейки и Садж', 'Сёмга', '100 г', 650, '650 ₽', 'филе атлантической сёмги, лимон, свежая зелень', NULL, NULL, '/assets/webp/steak_salmon-NdIQeT60.webp', 1, 10),
(37, 'mangal', 2, 'Стейки и Садж', 'Говядина', '100 г', 650, '650 ₽', 'отборная говядина, розмарин, пряности', NULL, NULL, '/assets/webp/steak_beef_ribeye-DnYGTLyI.webp', 1, 20),
(38, 'mangal', 2, 'Стейки и Садж', 'Свинина', '100 г', 450, '450 ₽', 'свиная шейка, специи', NULL, NULL, '/assets/webp/steak_pork-D3qQUQtV.webp', 1, 30),
(39, 'mangal', 2, 'Стейки и Садж', 'Садж', '1200 г', 3200, '3200 ₽', 'ассорти мяса, картофель, грибы, кабачки, болгарский перец, маринованный лук', NULL, NULL, '/assets/webp/sadzh_assorti-A6H5jTUA.webp', 1, 40),
(40, 'salads', 1, 'Мясные и Овощные', 'Белоснежка', '150 г', 400, '400 ₽', 'куриное филе, грибы, свежие огурцы, отварной картофель, отварная морковь, варёное яйцо, майонез', NULL, NULL, NULL, 1, 10),
(41, 'salads', 1, 'Мясные и Овощные', 'Цезарь с курицей', '150 г', 450, '450 ₽', 'куриное филе, листья салата, помидоры, сыр, сухари, соус цезарь', 'Классический салат с нежным куриным филе, хрустящими листьями салата, спелыми томатами, тёртым сыром и золотистыми сухариками под фирменным соусом цезарь.', NULL, '/assets/jpg/salad_caesar_chicken-B9mK4vX2.jpg', 1, 20),
(42, 'salads', 1, 'Мясные и Овощные', 'Греческий', '150 г', 500, '500 ₽', 'помидоры, свежие огурцы, перец болгарский, сыр фета, маслины, оливковое масло', 'Традиционный средиземноморский салат из сочных томатов, хрустящих огурцов, болгарского перца, нежного сыра фета и маслин, заправленный благородным оливковым маслом.', NULL, '/assets/webp/salad_greek-G7mN2vP4.webp', 1, 30),
(43, 'salads', 1, 'Мясные и Овощные', 'С хрустящим баклажаном', '150 г', 500, '500 ₽', 'хрустящие баклажаны, спелые помидоры, сливочный сыр фета, свежая зелень, кунжут, кисло-сладкий соус', 'Аппетитный салат с хрустящими обжаренными баклажанами, сочными томатами, нежным сыром фета, свежей зеленью и кунжутом под пикантной кисло-сладкой заправкой.', NULL, '/assets/webp/salad_crispy_eggplant-N4mK7vX3.webp', 1, 40),
(44, 'salads', 1, 'Мясные и Овощные', 'Оригинальный', '150 г', 500, '500 ₽', 'сочная курица, язык говяжий, помидоры, грибы маринованные', 'Изысканный салат из отборного отварного говяжьего языка, нежного филе курицы, спелых томатов и пикантных маринованных грибочков под фирменным соусом.', NULL, '/assets/jpg/salad_originalny-K8mN2vP5.jpg', 1, 50),
(45, 'salads', 1, 'Мясные и Овощные', 'Версаль', '150 г', 500, '500 ₽', 'курица, язык говяжий, морковча, помидор, пикантный соус (с горчицей)', 'Сытный праздничный салат с сочным куриным филе, отборным говяжьим языком, пикантной морковчой и спелыми помидорами под пикантным соусом с горчицей.', NULL, NULL, 1, 60),
(46, 'salads', 1, 'Мясные и Овощные', 'Римский', '150 г', 400, '400 ₽', 'листья салата, куриная грудка, помидоры, перец болгарский, медовая заправка', NULL, NULL, NULL, 1, 70),
(47, 'salads', 1, 'Мясные и Овощные', 'Матадор', '150 г', 500, '500 ₽', 'говядина, свежие овощи, зелень, пряная заправка', NULL, NULL, NULL, 1, 80),
(48, 'salads', 1, 'Мясные и Овощные', 'Салат Легкий', '150 г', 550, '550 ₽', 'креветки, свежие овощи, оливки, листья салата, медово-горчичная заправка (французская горчица), растительное масло', NULL, NULL, NULL, 1, 90),
(49, 'salads', 2, 'Рыбные и Деликатесные', 'Цезарь с креветками', '150 г', 550, '550 ₽', 'креветки, салатные листья, помидоры, сыр голландский, сухари, соус цезарь', 'Аппетитный салат с обжаренными креветками, свежими листьями салата, спелыми помидорами, голландским сыром и хрустящими сухарями под соусом цезарь.', 'Хит · Новинка', '/assets/webp/salad_caesar_shrimp-B7wK2mN4.webp', 1, 10),
(50, 'salads', 2, 'Рыбные и Деликатесные', 'Цезарь с сёмгой', '150 г', 500, '500 ₽', 'слабосолёная сёмга, салатные листья, помидоры, сыр, сухари, соус цезарь', 'Изысканный салат со слабосолёной сёмгой, хрустящими листьями салата, спелыми помидорами, тёртым сыром и золотистыми сухариками под фирменным соусом цезарь.', NULL, '/assets/webp/salad_caesar_salmon-S8mN2vP4.webp', 1, 20);
