(51, 'salads', 2, 'Рыбные и Деликатесные', 'Парус', '150 г', 500, '500 ₽', 'морковча, жареные грибы, обжаренное филе курицы, сыр, дольки куриного яйца, сметана', NULL, NULL, NULL, 1, 30),
(52, 'salads', 2, 'Рыбные и Деликатесные', 'Царский', '150 г', 500, '500 ₽', 'морковча, говядина обжаренная, перец, огурцы, заправка фирменная', 'Изысканный сытный салат с обжаренной сочной говядиной, пикантной морковчой, хрустящими свежими огурцами и сладким перцем под фирменной заправкой шефа с семенами кунжута.', NULL, '/assets/jpg/salad_tsarsky-C8mN2vP4.jpg', 1, 40),
(53, 'salads', 2, 'Рыбные и Деликатесные', 'Лагуна', '150 г', 500, '500 ₽', 'креветки, авокадо, свежие огурцы, помидоры, кунжут, фирменная заправка', NULL, NULL, '/assets/webp/salad_laguna-CV8n9K2w.webp', 1, 50),
(54, 'salads', 2, 'Рыбные и Деликатесные', 'Престиж', '150 г', 450, '450 ₽', 'отборное мясное филе, свежие овощи, маслины, фирменная заправка', NULL, NULL, '/assets/webp/salad_prestige-CK7mN2xL.webp', 1, 60),
(55, 'salads', 2, 'Рыбные и Деликатесные', 'Салат Каприз', '150 г', 450, '450 ₽', 'куриная печень, листья салата, помидоры, апельсин, медово-горчичная заправка, кунжут', NULL, 'Новинка', '/assets/webp/salad_kapriz-BR9xL2wQ.webp', 1, 70),
(56, 'salads', 2, 'Рыбные и Деликатесные', 'Салат Микс', '150 г', 500, '500 ₽', 'отварная свёкла, листья салата, сёмга, апельсин, брынза, медово-горчичная заправка', NULL, 'Новинка', NULL, 1, 80),
(57, 'starters', 1, 'Холодные закуски и тарелки', 'Рыбная тарелка', '250 г', 850, '850 ₽', NULL, NULL, NULL, '/assets/webp/fish_plate-D4QdCVY3.webp', 1, 10),
(58, 'starters', 1, 'Холодные закуски и тарелки', 'Мясная тарелка', '250 г', 800, '800 ₽', NULL, NULL, NULL, '/assets/webp/meat_plate-CXzSZEO-.webp', 1, 20),
(59, 'starters', 1, 'Холодные закуски и тарелки', 'Сырная тарелка', '250 г', 700, '700 ₽', NULL, NULL, NULL, '/assets/webp/cheese_plate-DkL3mP9x.webp', 1, 30),
(60, 'starters', 1, 'Холодные закуски и тарелки', 'Сельдь с гарниром', '500 г', 700, '700 ₽', NULL, NULL, NULL, '/assets/webp/food_herring_with_garnish-B7kQv9X2.webp', 1, 40),
(61, 'starters', 1, 'Холодные закуски и тарелки', 'Овощная тарелка', '250 г', 400, '400 ₽', 'хрустящие огурцы, спелые томаты, болгарский перец, морковча, свежая зелень', 'Свежая овощная нарезка: хрустящие огурцы, спелые томаты, болгарский перец, пряная морковча (морковь по-корейски), салат капустный и свежая зелень.', NULL, '/assets/webp/vegetable_plate-C4rK9wM5.webp', 1, 50),
(62, 'starters', 1, 'Холодные закуски и тарелки', 'Фруктовая тарелка', '250 г', 350, '350 ₽', 'яблоко, груша, апельсин, виноград', 'Красивая праздничная нарезка из свежих сочных фруктов: хрустящие сладкие яблоки, нежная груша, спелый апельсин и сладкий виноград.', NULL, '/assets/jpg/fruit_plate-B8mN2vP4.jpg', 1, 60),
(63, 'starters', 1, 'Холодные закуски и тарелки', 'Рулеты из баклажана', '150 г', 350, '350 ₽', 'обжаренные баклажаны, сыр, грецкий орех, чеснок, свежая зелень', 'Нежные рулетики из обжаренных баклажанов с пикантной начинкой из сыра, чеснока и свежей зелени, посыпанные дроблёным грецким орехом.', NULL, '/assets/webp/eggplant_rolls-E9mK2wQ4.webp', 1, 70),
(64, 'starters', 1, 'Холодные закуски и тарелки', 'Закуска Мексиканская', '190 г', 500, '500 ₽', 'морковча, ветчина, язык говяжий, маринованные огурцы, болгарский перец, заправка: растительное масло', NULL, NULL, NULL, 1, 80),
(65, 'starters', 2, 'Горячие закуски и снеки', 'Креветки в пикантном соусе', '175 г', 750, '750 ₽', 'тигровые креветки, авторский пикантный соус, белый и чёрный кунжут, свежий лимон, зелень петрушки', 'Сочные тигровые креветки, обжаренные до золотистой корочки в авторском пряно-пикантном соусе. Подаются с миксом белого и чёрного кунжута, дольками свежего лимона и свежей зеленью на бамбуковых шпажках.', NULL, '/assets/webp/shrimp_spicy_sauce-K7mN2vX4.webp', 1, 10),
(66, 'starters', 2, 'Горячие закуски и снеки', 'Цезарь-ролл запечённый', '150 г', 450, '450 ₽', 'тонкий лаваш, куриное филе, свежие листья салата, помидоры, сыр, соус цезарь', 'Аппетитная горячая закуска: запечённый в тонком лаваше ролл с сочным куриным филе, свежими листьями салата, помидорами, расплавленным сыром и соусом цезарь.', 'Новинка', '/assets/webp/cezar_roll_baked-B8mN2vP4.webp', 1, 20),
(67, 'starters', 2, 'Горячие закуски и снеки', 'Конвертики с курицей', '170 г', 400, '400 ₽', 'тонкий лаваш, куриное филе, болгарский перец, сыр, специи', 'Румяные хрустящие конвертики из тонкого лаваша с сочной начинкой из куриного филе, сладкого перца и тягучего сыра, украшенные фирменным соусом и кунжутом.', NULL, '/assets/jpg/envelopes_chicken-K4mN8vX2.jpg', 1, 30),
(68, 'starters', 2, 'Горячие закуски и снеки', 'Конвертики с грибами', '170 г', 350, '350 ₽', 'лаваш, грибы, сыр', NULL, NULL, '/uploads/img_1791581773578_h7xyyg.jpg', 1, 40),
(69, 'starters', 2, 'Горячие закуски и снеки', 'Сырные палочки', '100 г', 250, '250 ₽', 'тягучий сыр, хрустящая панировка, специи', 'Аппетитные сырные палочки в золотистой хрустящей панировке с нежной тягучей сырной начинкой внутри. Подаются горячими.', NULL, '/assets/jpg/cheese_sticks-S7mK3vP9.jpg', 1, 50),
(70, 'starters', 2, 'Горячие закуски и снеки', 'Наггетсы', '100 г', 200, '200 ₽', 'нежное куриное филе, хрустящая панировка, специи', 'Хрустящие куриные наггетсы из отборного филе в золотистой панировке. Нежные и сочные внутри — классика любимых горячих закусок.', NULL, '/assets/jpg/nuggets-K7mN3vL9.jpg', 1, 60),
(71, 'starters', 2, 'Горячие закуски и снеки', 'Луковые кольца', '100 г', 200, '200 ₽', 'репчатый лук, яйцо, панировочные сухари, специи', 'Аппетитные кольца репчатого лука в нежном хрустящем кляре и золотистой панировке, обжаренные до идеальной корочки. Отличная горячая закуска.', NULL, '/assets/jpg/onion_rings-B8mN2vP4.jpg', 1, 70),
(72, 'starters', 2, 'Горячие закуски и снеки', 'Гренки с чесноком', '100 г', 200, '200 ₽', 'ржаной бородинский хлеб, чесночное масло, чеснок, морская соль', 'Хрустящие и ароматные брусочки ржаного хлеба, обжаренные до золотистой корочки и пропитанные пикантным чесночным маслом с солью. Идеальная горячая закуска к любым напиткам.', NULL, '/assets/jpg/croutons_garlic-B8mN2vP4.jpg', 1, 80),
(73, 'hot', 1, 'Первые блюда', 'Солянка сборная', '250 г', 320, '320 ₽', 'наваристый мясной бульон, мясные деликатесы, солёные огурцы, маслины, лимон, свежий укроп, сметанный соус', 'Классическая домашняя мясная сборная солянка на крепком наваристом бульоне с копчёностями, солёными огурчиками, маслинами, долькой сочного лимона и свежей зеленью.', NULL, '/assets/jpg/solyanka-V2xK8mP4.jpg', 1, 10),
(74, 'hot', 1, 'Первые блюда', 'Пельмени с бульоном', '200 г', 300, '300 ₽', 'домашние пельмени, наваристый мясной бульон, свежий укроп', NULL, NULL, '/assets/webp/pelmeni_broth-B7kN9wL2.webp', 1, 20),
(75, 'hot', 1, 'Первые блюда', 'Бульон с фрикадельками', '200 г', 300, '300 ₽', NULL, NULL, NULL, NULL, 1, 30),
(76, 'hot', 1, 'Первые блюда', 'Лапша домашняя с курицей', '200/50 г', 250, '250 ₽', 'домашняя яичная лапша, сочное куриное филе, прозрачный наваристый бульон, свежий укроп', 'Традиционный домашний суп на прозрачном наваристом курином бульоне с нежным куриным филе, тонкой домашней лапшой и свежей зеленью укропа.', NULL, '/assets/webp/soup_noodles_chicken-H7mN2vP4.webp', 1, 40),
(77, 'hot', 2, 'Вторые блюда', 'Чанахи с говядиной', '250 г', 750, '750 ₽', 'нежная говядина, картофель, баклажаны, томаты, сладкий перец, чеснок, свежая зелень', 'Традиционное сытное грузинское блюдо из сочной томлёной говядины с картофелем, баклажанами, сладким перцем, спелыми томатами и пряной зеленью в глиняном горшочке.', NULL, '/assets/jpg/chanahi-K8mN2vP4.jpg', 1, 10),
(78, 'hot', 2, 'Вторые блюда', 'Жаркое по-армянски', '250 г', 650, '650 ₽', 'говядина, картофель, болгарский перец, лук, томаты, кавказские специи, зелень', NULL, NULL, '/images/placeholder_dish.svg', 1, 20),
(79, 'hot', 2, 'Вторые блюда', 'Свинина с овощами', '150 г', 650, '650 ₽', 'сочная свинина, баклажаны, сладкий перец, спелые томаты, свежая зелень, тонкий лаваш', 'Ароматные кусочки нежной свинины, обжаренные с баклажанами, сочными томатами, сладким перцем и свежей зеленью. Подаются на тонком лаваше в чугунной сковороде.', 'Новинка', '/assets/jpg/pork_vegetables-C8kN2vP4.jpg', 1, 30),
(80, 'hot', 2, 'Вторые блюда', 'Свинина в соусе с грибами', '150 г', 630, '630 ₽', 'свиная вырезка, свежие шампиньоны, сливочный соус, лук, зелень', 'Сочные кусочки свинины, обжаренные до золотистого цвета и томленые в густом ароматном сливочно-грибном соусе.', 'Новинка', '/assets/webp/pork_mushroom_sauce-D8mK4vP2.webp', 1, 40),
(81, 'hot', 2, 'Вторые блюда', 'Печень по-татарски', '150 г', 600, '600 ₽', 'говяжья печень, лук репчатый, маринованные огурцы, томатный соус, зелень, тонкий лаваш', 'Нежная говяжья печень, обжаренная с репчатым луком, маринованными огурчиками и восточными специями в томатном соусе. Подаётся на тонком лаваше со сладким перцем и свежей зеленью.', NULL, '/assets/webp/liver_tatar-B8mK9wM7.webp', 1, 50),
(82, 'hot', 2, 'Вторые блюда', 'Куриная грудка с овощами', '200 г', 550, '550 ₽', 'куриное филе, сочные овощи, яйцо и сыр перемешиваются и запекаются вместе с блюдом', NULL, NULL, '/uploads/img_1791577952800_j5vasm.jpg', 1, 60),
(83, 'hot', 2, 'Вторые блюда', 'Рагу овощное с курицей', '250 г', 550, '550 ₽', 'куриное филе, картофель, кабачки, болгарский перец, томаты, лук репчатый, свежая зелень укропа, бульон, специи', 'Сытное и ароматное рагу из нежного куриного филе с картофелем, кабачками, сладким болгарским перцем, томатами и свежей зеленью, запечённое в традиционном глиняном горшочке.', NULL, '/assets/webp/food_ragu_chicken-M5kP9vX2.webp', 1, 70),
(84, 'hot', 2, 'Вторые блюда', 'Китайский дракон', '170 г', 500, '500 ₽', 'куриное филе, лук репчатый, перец болгарский, маринованные огурцы, зелень, кунжут', NULL, NULL, '/images/placeholder_dish.svg', 1, 80),
(85, 'hot', 2, 'Вторые блюда', 'Курица по-гавайски', '150 г', 500, '500 ₽', NULL, NULL, 'Новинка', '/images/placeholder_dish.svg', 1, 90),
(86, 'hot', 2, 'Вторые блюда', 'Курица по-французски', '150 г', 450, '450 ₽', 'куриное филе, спелые помидоры, сыр, репчатый лук, фирменный соус', 'Сочное куриное филе, запечённое со спелыми томатами под аппетитной сырной корочкой и пикантным авторским соусом.', 'Новинка', '/assets/webp/chicken_french-K7rP2wL9.webp', 1, 100),
(87, 'hot', 2, 'Вторые блюда', 'Дорадо', '100 г', 450, '450 ₽', 'целая рыба дорадо, специи, лимон, свежая зелень, сладкий перец', 'Целая запечённая рыба дорадо с золотистой корочкой, дольками лимона, прованскими травами и свежей зеленью на фирменном рыбном блюде.', NULL, '/assets/webp/fish_dorado-K9mN4vX6.webp', 1, 110),
(88, 'hot', 2, 'Вторые блюда', 'Горбуша под овощами', '150 г', 400, '400 ₽', 'филе сочной горбуши, морковь, лук, сладкий перец, сырная корочка, лимон, зелень', 'Нежное и сочное филе горбуши, запечённое под аппетитной овощной подушкой из сладкой моркови, лука и перца под золотистой сырной корочкой. Подаётся с ломтиками лимона и свежей зеленью.', 'Новинка', '/assets/jpg/gorbusha_hot-B8mN2vP4.jpg', 1, 120),
(89, 'hot', 2, 'Вторые блюда', 'Удон с креветками', '150 г', 400, '400 ₽', 'японская пшеничная лапша удон, тигровые креветки, овощи, пряный соус, кунжут', 'Японская пшеничная лапша удон с тигровыми креветками в пряном соусе с овощами и кунжутом.', 'Новинка', '/assets/webp/udon_shrimp-T7mN2vP4.webp', 1, 130),
(90, 'hot', 2, 'Вторые блюда', 'Удон с курицей', '150 г', 350, '350 ₽', 'лапша удон ручной работы собственного приготовления, куриное филе, овощи, соус терияки', NULL, 'Новинка', '/assets/webp/udon_chicken-CV9kL3wQ.webp', 1, 140),
(91, 'hot', 2, 'Вторые блюда', 'Удон с грибами', '150 г', 350, '350 ₽', 'пшеничная лапша удон, свежие шампиньоны, овощи, ароматный соус, кунжут', NULL, 'Новинка', NULL, 1, 150),
(92, 'hot', 2, 'Вторые блюда', 'Жареные пельмени с говядиной', '150 г', 300, '300 ₽', 'сочная рубленая говядина, пряности, хрустящее тесто, соус, огурец', NULL, NULL, '/assets/webp/fried_dumplings_beef-B3kNm9xL.webp', 1, 160),
(93, 'hot', 2, 'Вторые блюда', 'Жареные пельмени с курицей', '150 г', 280, '280 ₽', 'домашние пельмени с куриным фаршем, обжаренные до золотистой корочки, соус, огурчик', 'Нежные домашние пельмени с куриным фаршем, обжаренные до золотистой хрустящей корочки на сковороде, подаются с пикантным соусом и свежим огурчиком.', NULL, '/assets/webp/fried_dumplings_chicken-K7mN4vP2.webp', 1, 170),
(94, 'garnishes', 1, 'Гарниры', 'Булгур с овощами', '200 г', 300, '300 ₽', 'булгур, сладкая кукуруза, морковь, шампиньоны, пряные травы, свежая петрушка', 'Аппетитный рассыпчатый булгур, приготовленный с зернами сладкой кукурузы, кусочками моркови, шампиньонами и душистыми травами. Идеальный гарнир к мясным и рыбным блюдам.', NULL, '/assets/jpg/bulgur_vegetables-B8mN2vP4.jpg', 1, 10),
(95, 'garnishes', 1, 'Гарниры', 'Овощи запечённые', '100 г', 250, '250 ₽', 'сезонные овощи, кабачки, болгарский перец, шампиньоны, пряные травы', 'Аппетитные сезонные овощи, запечённые до сочности и лёгкого румянца: кружочки кабачков, сладкий болгарский перец и шампиньоны с пряными травами.', NULL, '/assets/webp/baked_vegetables-H3mK9wB8.webp', 1, 20),
(96, 'garnishes', 1, 'Гарниры', 'Картофель с чесноком', '150 г', 220, '220 ₽', 'картофель, чеснок, пряные травы, растительное масло', NULL, NULL, '/images/placeholder_dish.svg', 1, 30),
(97, 'garnishes', 1, 'Гарниры', 'Запечённый картофель', '150 г', 200, '200 ₽', 'картофель, ароматные специи, растительное масло', 'Золотистые ломтики рифлёного картофеля, запечённые до аппетитной хрустящей корочки с ароматными травами и пряностями.', NULL, '/assets/jpg/baked_potato-P4mN8vK2.jpg', 1, 40),
(98, 'garnishes', 1, 'Гарниры', 'Фасоль стручковая', '150 г', 200, '200 ₽', 'зеленая стручковая фасоль, сливочное масло, чеснок, специи, свежая зелень', NULL, 'Новинка', NULL, 1, 50),
(99, 'garnishes', 1, 'Гарниры', 'Картофель фри', '100 г', 170, '170 ₽', 'хрустящий рифлёный картофель, растительное масло, соль', 'Золотистый хрустящий рифлёный картофель фри, обжаренный до идеальной аппетитной корочки и слегка присыпанный солью.', NULL, '/assets/jpg/french_fries-B7mN2vP4.jpg', 1, 60),
(100, 'bread', 1, 'Хлеб и выпечка', 'Лаваш', '100 г', 100, '100 ₽', 'свежий тонкий кавказский лаваш', 'Традиционный свежеиспечённый тонкий кавказский лаваш, мягкий и ароматный. Идеальное дополнение к шашлыку и горячим блюдам.', NULL, '/assets/jpg/bread_lavash-K8mN2vP4.jpg', 1, 10);
