(101, 'bread', 1, 'Хлеб и выпечка', 'Булочка', '60 г', 30, '30 ₽', 'свежая мягкая булочка из собственной выпечки кафе', 'Румяная, воздушная и мягкая булочка собственной выпечки кафе, посыпанная семенами белого и чёрного кунжута.', NULL, '/assets/jpg/bread_bun-B8mN2vP4.jpg', 1, 20),
(102, 'pizza', 1, 'Пицца', 'Пепперони', NULL, 550, '550 ₽', 'пикантная колбаса пепперони, сыр моцарелла, томатный соус, прованские травы', 'Фирменная пицца на тонком тесте с пикантной колбасой пепперони, томатным соусом и тягучим сыром моцарелла.', 'Хит', '/assets/webp/pizza_pepperoni-P8mK2wL5.webp', 1, 10),
(103, 'pizza', 1, 'Пицца', 'Грибная поляна', NULL, 550, '550 ₽', 'шампиньоны, сырный соус, майонез, сыр моцарелла, зелень', 'Горячая фирменная пицца на тонком хрустящем тесте со свежими шампиньонами, аппетитным сырным соусом, майонезом и расплавленным тягучим сыром моцарелла.', NULL, '/assets/webp/pizza_gribnaya-M8kL2vX5.webp', 1, 20),
(104, 'pizza', 1, 'Пицца', 'Гавайская', NULL, 550, '550 ₽', 'куриное филе, сочные ананасы, соус цезарь, сыр моцарелла', 'Классическая аппетитная пицца с сочным куриным филе, кусочками сладкого ананаса, нежным соусом цезарь и щедрым слоем тягучей моцареллы.', NULL, '/assets/webp/pizza_hawaiian-W4rM8kL2.webp', 1, 30),
(105, 'pizza', 1, 'Пицца', 'Сырная', NULL, 550, '550 ₽', 'сыр моцарелла, благородные сыры, нежный сливочный соус, фирменное тесто', NULL, NULL, '/assets/webp/pizza_cheese-D9kM2wLx.webp', 1, 40),
(106, 'pizza', 1, 'Пицца', 'Маргарита', NULL, 500, '500 ₽', 'спелые помидоры, сыр моцарелла, томатный соус, прованские травы, тонкое тесто', 'Классическая пицца на тонком тесте со спелыми томатами, ароматными травами и расплавленным тягучим сыром моцарелла.', NULL, '/assets/webp/pizza_margarita-H4mN8vX2.webp', 1, 50),
(107, 'sauces', 1, 'Фирменные соусы', 'Тар-тар', '30 г', 70, '70 ₽', 'классический соус на майонезной основе с маринованными огурчиками и укропом', 'Нежный пикантный соус тар-тар на кремовой майонезной основе с добавлением хрустящих маринованных огурчиков, свежего укропа и нотки лимонного сока. Идеально подходит к рыбе, морепродуктам и хрустящим закускам.', NULL, '/assets/jpg/sauce_tartar-B8mN2vP4.jpg', 1, 10),
(108, 'sauces', 1, 'Фирменные соусы', 'Барбекю', '30 г', 70, '70 ₽', NULL, NULL, NULL, '/images/placeholder_dish.svg', 1, 20),
(109, 'sauces', 1, 'Фирменные соусы', 'Чесночный', '30 г', 70, '70 ₽', 'сливочно-чесночный соус со свежей зеленью', 'Нежный и пикантный сливочно-чесночный соус со свежим укропом и зеленью петрушки. Идеально подходит к мясу, шашлыку и горячим закускам.', NULL, '/assets/jpg/sauce_garlic-B8mN2vP4.jpg', 1, 30),
(110, 'sauces', 1, 'Фирменные соусы', 'Сырный', '30 г', 70, '70 ₽', NULL, NULL, NULL, '/images/placeholder_dish.svg', 1, 40),
(111, 'sauces', 1, 'Фирменные соусы', 'Терияки', '30 г', 70, '70 ₽', 'традиционный японский карамельно-соевый соус', 'Классический японский густой соус терияки с карамельно-соевым вкусом и легким ароматом пряностей. Идеально подчеркивает вкус птицы, мяса, рыбы и блюд вок.', NULL, '/assets/jpg/sauce_teriyaki-B8mN2vP4.jpg', 1, 50),
(112, 'sauces', 1, 'Фирменные соусы', 'Манго-чили', '30 г', 70, '70 ₽', NULL, NULL, NULL, '/images/placeholder_dish.svg', 1, 60),
(113, 'sauces', 1, 'Фирменные соусы', 'Кавказский', '30 г', 70, '70 ₽', 'пряный томатный соус со свежими кавказскими травами и чесноком', 'Ароматный пряный томатный соус со свежей кинзой, базиликом, чесноком и традиционными кавказскими специями. Превосходно дополняет шашлык, люля-кебаб и жареное мясо.', NULL, '/assets/jpg/sauce_caucasian-B8mN2vP4.jpg', 1, 70),
