(192, 'bar', 8, 'Безалкогольные напитки и коктейли', 'Соки (в ассортименте)', '1 л', 300, '300 ₽', NULL, NULL, NULL, NULL, 1, 40),
(193, 'bar', 8, 'Безалкогольные напитки и коктейли', 'Кола', '1 л', 250, '250 ₽', NULL, NULL, NULL, NULL, 1, 50),
(194, 'banquet_dishes', 1, 'Салаты', 'Тбилиси', '150 г', 500, '500 ₽', 'отварная говядина, красная фасоль, болгарский перец, красный лук, грецкие орехи, кинза, чеснок, оливковое масло, хмели-сунели', 'Традиционный грузинский салат с нежной отварной говядиной, красной фасолью, хрустящим болгарским перцем и грецкими орехами с пикантной заправкой.', NULL, '/assets/webp/salad_tbilisi-D8wK2mN1.webp', 1, 10),
(195, 'banquet_dishes', 1, 'Салаты', 'Гнездо', '150 г', 480, '480 ₽', 'куриное филе, ветчина, маринованные шампиньоны, яйца куриные и перепелиные, хрустящий картофель пай, сыр, майонез, свежая зелень', 'Эффектный праздничный салат с нежным куриным филе, ветчиной, грибами и золотистым хрустящим картофелем пай в виде гнезда с перепелиными яйцами.', NULL, '/assets/jpg/salad_gnezdo-N8mK2vP4.jpg', 1, 20),
(196, 'banquet_dishes', 1, 'Салаты', 'Мужские грёзы', '150 г', 500, '500 ₽', 'отборная отварная говядина, маринованный в яблочном уксусе лук, куриное яйцо, твёрдый сыр, майонез', 'Сытный и благородный слоёный салат с сочной отварной говядиной, пикантным маринованным луком, отборным сыром и нежным соусом.', NULL, NULL, 1, 30),
(197, 'banquet_dishes', 1, 'Салаты', 'Сельдь под шубой', '150 г', 450, '450 ₽', 'слабосолёное филе сельди, отварной картофель, сладкая свёкла, морковь, куриное яйцо, репчатый лук, майонез, свежая зелень', 'Любимая классика праздничного застолья: нежные слои пряной слабосолёной сельди, отварных овощей и воздушного соуса с ярким оформлением.', NULL, '/assets/webp/food_herring_fur_coat-CB_oW59t.webp', 1, 40),
(198, 'banquet_dishes', 1, 'Салаты', 'Капитоль', '150 г', 450, '450 ₽', 'обжаренное куриное филе, сочная ветчина, свежие огурцы, сыр, томаты черри, салатные листья, фирменный соус', 'Изысканный банкетный салат с гармоничным сочетанием куриного филе, ветчины, свежих хрустящих огурцов и нежного тёртого сыра.', NULL, '/assets/webp/salad_kapitol-E2mK9vX1.webp', 1, 50),
(199, 'banquet_dishes', 2, 'Закуски', 'Ажурные блины с семгой', '150 г', 450, '450 ₽', 'домашние ажурные блинчики, слабосолёная атлантическая сёмга, сливочный творожный сыр, свежие листья салата, маслины, зелень', 'Тончайшие узорные блинчики с начинкой из ломтиков слабосолёной сёмги и сливочного творожного крем-сыра со свежей зеленью.', NULL, '/assets/webp/food_salmon_lace_crepes-rWFqp0Rb.webp', 1, 10),
(200, 'banquet_dishes', 2, 'Закуски', 'Тарталетки с семгой', '100 г', 400, '400 ₽', 'рассыпчатые песочные тарталетки, слабосолёная сёмга, нежный сливочный крем-сыр, свежий огурец, укроп', 'Изящная банкетная закуска в хрустящих песочных тарталетках с нежным творожно-сливочным муссом и ломтиками благородной сёмги.', NULL, NULL, 1, 20);
INSERT INTO `dishes` (`id`, `category_ref`, `section_id`, `section_title`, `name`, `weight`, `price`, `price_text`, `note`, `description`, `tag`, `img`, `is_available`, `sort_order`) VALUES
(201, 'banquet_dishes', 2, 'Закуски', 'Рыба в кляре', '150 г', 400, '400 ₽', 'нежное филе белой рыбы, воздушный золотистый кляр, дольки свежего лимона, веточка петрушки', 'Сочные кусочки отборного рыбного филе в хрустящем золотистом кляре. Подаётся с дольками лимона и свежей зеленью.', NULL, '/assets/webp/food_fish_in_batter-0PXgUEom.webp', 1, 30),
(202, 'banquet_dishes', 2, 'Закуски', 'Горбуша под овощами', '150 г', 400, '400 ₽', 'филе сочной горбуши, пассерованная сладкая морковь, репчатый лук, болгарский перец, сырная корочка, специи', 'Нежное филе горбуши, запечённое под сочной овощной подушкой с сырной корочкой по банкетному рецепту.', NULL, '/assets/webp/food_gorbusha_vegetables-H3mN8vX2.webp', 1, 40),
(203, 'banquet_dishes', 2, 'Закуски', 'Торт из печени', '150 г', 400, '400 ₽', 'нежные домашние печёночные коржи, пассерованная морковь с луком, чесночный соус, рубленый свежий укроп, икринки для декора', 'Знаменитая банкетная закуска: нежнейшие печёночные коржи, прослоенные сладкой пассерованной морковью с луком и ароматным чесночным соусом.', NULL, '/assets/webp/food_liver_cake-gOqa18IE.webp', 1, 50),
(204, 'banquet_dishes', 2, 'Закуски', 'Фаршированные грибы', '150 г', 350, '350 ₽', 'крупные шляпки шампиньонов, рубленое куриное филе, сыр моцарелла, чеснок, сливочный соус, свежая зелень', 'Запечённые шляпки свежих шампиньонов, наполненные сочной куриной начинкой под расплавленным золотистым сыром.', NULL, '/assets/jpg/stuffed_mushrooms-B8mN2vP4.jpg', 1, 60),
(205, 'banquet_dishes', 2, 'Закуски', 'Тарталетки с жульеном', '100 г', 300, '300 ₽', 'хрустящие тарталетки, шампиньоны, куриное филе, сливки, сырная корочка', 'Ароматный классический грибной жульен с курицей в порционных тарталетках под аппетитной сырной корочкой.', NULL, NULL, 1, 70),
(206, 'banquet_dishes', 2, 'Закуски', 'Рулетики из ветчины с сыром', '150 г', 300, '300 ₽', 'отборная ветчина, тёртый сыр, куриное яйцо, чеснок, майонез, перья зелёного лука', 'Тонкие слайсы нежной ветчины с пикантной начинкой из тёртого сыра с чесноком и яйцом, перевязанные зелёным луком.', NULL, '/assets/webp/ham_rolls_cheese-B7kL9wM2.webp', 1, 80),
(207, 'banquet_dishes', 2, 'Закуски', 'Куриный рулет с черносливом', '150 г', 450, '450 ₽', 'куриное филе, вяленый чернослив, дроблёные грецкие орехи, пряные травы, чеснок', 'Нежный рулет из куриного филе с изысканной сладостью чернослива и ароматом грецких орехов в тонкой нарезке.', NULL, NULL, 1, 90),
(208, 'banquet_dishes', 3, 'Первые блюда', 'Шурпа', '200 г', 350, '350 ₽', 'наваристый говяжий бульон, сочная говядина на косточке, крупный картофель, сладкая морковь, лук, свежая кинза и восточные специи', 'Традиционный восточный суп на прозрачном ароматном бульоне с сочным мясом, крупными кусочками овощей и пряными травами.', NULL, '/assets/webp/soup_shurpa-B4mK8vX3.webp', 1, 10),
(209, 'banquet_dishes', 3, 'Первые блюда', 'Суп грибной', '200 г', 300, '300 ₽', 'ароматные лесные грибы и шампиньоны, картофель, пассерованная морковь с луком, сливочное масло, свежая зелень', 'Наваристый и душистый суп из грибов с картофелем и нежной пассеровкой на сливочном масле со свежей зеленью.', NULL, NULL, 1, 20),
(210, 'banquet_dishes', 4, 'Вторые блюда', 'Шапка Мономаха', '150 г', 500, '500 ₽', 'отборная мясная вырезка, свежие шампиньоны, томаты, сыр моцарелла, майонезный соус, зёрна спелого граната, зелень', 'Царское банкетное блюдо: сочное мясо, запечённое слоями с грибами, помидорами и золотистым сыром, украшенное рубиновыми зёрнами граната.', NULL, NULL, 1, 10),
(211, 'banquet_dishes', 4, 'Вторые блюда', 'Деликатесное', '150 г', 500, '500 ₽', 'нежная мясная вырезка, сладкий ананас, болгарский перец, твёрдый сыр, фирменный соус от шефа', 'Изысканное банкетное горячее блюдо с гармоничным контрастом сочного мяса, тропического ананаса и сливочного сыра.', NULL, NULL, 1, 20),
(212, 'banquet_dishes', 4, 'Вторые блюда', 'Куриное филе с грибами', '150 г', 480, '480 ₽', 'куриная грудка, свежие шампиньоны, репчатый лук, сливки, сыр, пряные травы', 'Нежнейшее куриное филе, запечённое с лесными шампиньонами в сливочном соусе под расплавленным сыром.', NULL, '/assets/webp/chicken_fillet_mushrooms-B8xN3kLQ.webp', 1, 30),
(213, 'banquet_dishes', 4, 'Вторые блюда', 'Нежность', '150 г', 480, '480 ₽', 'куриное филе, спелые томаты, сыр, чесночно-сметанный соус, свежая зелень', 'Блюдо полностью оправдывает название: тающее во рту куриное филе под томатной подушкой и сырной корочкой со сметанно-чесночным ароматом.', NULL, NULL, 1, 40),
(214, 'banquet_dishes', 4, 'Вторые блюда', 'Манты', '150 г', 500, '500 ₽', 'тонкое домашнее тесто, рубленая говядина, репчатый лук, восточные пряности, сливочное масло', 'Традиционные домашние манты на пару с сочной начинкой из рубленой говядины с пряностями и ароматным бульоном внутри.', NULL, NULL, 1, 50),
(215, 'banquet_dishes', 4, 'Вторые блюда', 'Голубцы', '150 г', 450, '450 ₽', 'нежные капустные листья, сочный фарш из говядины и свинины, отборный рис, томатно-сметанный соус, свежая зелень', 'Аппетитные домашние голубцы в тонких капустных листьях с сытным мясным фаршем, томлёные в густом томатно-сметанном соусе.', NULL, NULL, 1, 60),
(216, 'banquet', 1, 'Банкетное обслуживание', 'Банкет', NULL, 2200, 'от 2200 ₽/чел.', NULL, NULL, NULL, '/assets/webp/banquet_table_top-d5WdaHV8.webp', 1, 10),
