(255, 'bar', 8, 'Безалкогольные напитки и коктейли', 'Вода «BonAqua» без газа 0,5 л', '0,5 л', 100, '100 ₽', 'бутилированная питьевая вода без газа', 'Кристально чистая природная питьевая вода BonAqua без газа в удобной бутылке 0,5 л.', NULL, NULL, 1, 10),
(256, 'bar', 8, 'Безалкогольные напитки и коктейли', 'Вода «BonAqua» с газом 0,5 л', '0,5 л', 100, '100 ₽', 'бутилированная газированная вода', 'Освежающая газированная питьевая вода BonAqua с мягкой газацией в бутылке 0,5 л.', NULL, NULL, 1, 20),
(257, 'bar', 8, 'Безалкогольные напитки и коктейли', 'Вода «BonAqua» без газа 1 л', '1 л', 150, '150 ₽', 'бутилированная питьевая вода без газа', 'Кристально чистая природная питьевая вода BonAqua без газа в бутылке 1 л.', NULL, NULL, 1, 30),
(258, 'bar', 8, 'Безалкогольные напитки и коктейли', 'Вода «BonAqua» с газом 1 л', '1 л', 150, '150 ₽', 'бутилированная газированная вода', 'Освежающая газированная питьевая вода BonAqua с мягкой газацией в бутылке 1 л.', NULL, NULL, 1, 40),
(259, 'tea_coffee', 1, 'Чай и чайные наборы', 'Чай в чайнике с облепихой', '500 мл', 220, '220 ₽', 'чёрный чай, сочная сибирская облепиха, мёд или сахар по вкусу', 'Ароматный витаминный чай с сочными ягодами сибирской облепихи, заваренный в прозрачном чайнике на подставке со свечой. Обладает приятной кислинкой и насыщенным согревающим вкусом.', NULL, '/assets/jpg/tea_seabuckthorn-B8mN2vP4.jpg', 1, 95),
(260, 'tea_coffee', 1, 'Чай и чайные наборы', 'Чай в чайнике с облепихой', '1500 мл', 400, '400 ₽', 'чёрный чай, сочная сибирская облепиха, мёд или сахар по вкусу', 'Ароматный витаминный чай с сочными ягодами сибирской облепихи, заваренный в прозрачном чайнике на подставке со свечой. Обладает приятной кислинкой и насыщенным согревающим вкусом.', NULL, '/assets/jpg/tea_seabuckthorn-B8mN2vP4.jpg', 1, 96);
INSERT INTO `promotions` (`id`, `category`, `tag`, `badge`, `title`, `subtitle`, `description`, `bonus_label`, `bonus`, `action_label`, `action_type`, `img`, `is_active`, `sort_order`) VALUES
(1, 'birthday', 'Именинникам', '-5% наличными', 'Скидка на День Рождения', 'Отпразднуйте с выгодой и размахом', 'Дарим скидку 5% на всё меню кухни в ваш день рождения, а также 3 дня до и 3 дня после праздника. Для активации акции потребуется предъявить паспорт в кафе при расчёте. Живая музыка и поздравление от заведения.', 'Условие акции:', 'Скидка 5% действует при предъявлении паспорта и оплате наличными', 'Забронировать', 'table', NULL, 1, 10),
(2, 'banquet', 'Банкеты', 'Свои напитки и фрукты', 'Заказ банкета «Под ключ»', 'Юбилеи, праздники и памятные даты', 'Индивидуальный расчет меню от 2200 ₽/чел. Вместительные залы до 150 и до 25 персон с профессиональным световым и звуковым оборудованием, сценой и танцполом. Разрешены свои напитки и фрукты.', 'Бонус:', 'Свои напитки и фрукты без пробкового сбора', 'Забронировать', 'event', NULL, 1, 20),
(3, 'wedding', 'Свадьба', '-5% наличными', 'Свадебное торжество', 'Главный день в красивом банкетном зале', 'Торжественный банкет в просторном зале до 150 посадочных мест со сценой и танцполом. Скидка 5% на свадебное банкетное меню предоставляется только при оплате наличными.', 'Условие акции:', 'Скидка 5% действует при оплате наличными', 'Забронировать', 'event', NULL, 1, 30);
INSERT INTO `halls` (`id`, `name`, `slug`, `capacity`, `description`, `features`, `img`, `photos`, `sort_order`, `is_active`) VALUES
(1, 'Большой банкетный зал', 'main', 'до 150 персон', 'Величественный зал с высокими сводчатыми потолками, колоннами и торжественным убранством. Оснащен сценой, большим танцполом, профессиональным световым и акустическим оборудованием. Идеально подходит для проведения свадеб, масштабных юбилеев, выпускных и новогодних корпоративов.', '[''Вместимость: до 150 посадочных мест'', ''Сцена, танцпол и профессиональный звук'', ''Возможность индивидуальной рассадки гостей'', ''Просторная зона для фотосессии и первого танца'']', '/assets/webp/hall_main_dancefloor-DDEYboG4.webp', '[{''src'': ''/assets/webp/hall_main_dancefloor-DDEYboG4.webp'', ''title'': ''Танцпол и панорама зала'', ''desc'': ''Просторный танцпол с узорным центром и концертным светом для ярких торжеств'', ''alt'': ''Большой банкетный зал: просторный танцпол и праздничная иллюминация''}, {''src'': ''/assets/webp/hall_main_stage-LHCo79Kn.webp'', ''title'': ''Сцена и живой звук'', ''desc'': ''Подиум с подсветкой, акустическое оборудование и барельеф «Белоснежка»'', ''alt'': ''Большой банкетный зал: профессиональная сцена для живой музыки''}, {''src'': ''/assets/webp/hall_main_bar-CgExjKXM.webp'', ''title'': ''Барная зона «Белоснежка»'', ''desc'': ''Барная стойка со светящейся вывеской, напитками и подсветкой'', ''alt'': ''Большой банкетный зал: фирменный бар «Белоснежка»''}, {''src'': ''/assets/webp/hall_main_tables-BWH-sCjJ.webp'', ''title'': ''Банкетная зона и диваны'', ''desc'': ''Комфортная посадка гостей, мягкие диваны и живописное настенное панно'', ''alt'': ''Большой банкетный зал: банкетная зона с диванами и художественным панно''}, {''src'': ''/assets/webp/hall_main_lounge-BBt0F-Ax.webp'', ''title'': ''Лаунж с винной витриной'', ''desc'': ''Уютный мягкий уголок с диванами, телевизором и коллекционной витриной'', ''alt'': ''Большой банкетный зал: уютная лаунж-зона с винной витриной''}, {''src'': ''/assets/webp/hall_main_panorama-DdLej2El.webp'', ''title'': ''Торжественная рассадка'', ''desc'': ''Вместимость до 150 гостей, колонны и сияющие звёзды под потолком'', ''alt'': ''Большой банкетный зал: вид на зал и торжественную рассадку''}]', 1, 1),
(2, 'Малый банкетный зал', 'small', 'до 25 персон', 'Уютное и уединенное пространство для душевных праздников в кругу самых близких. Прекрасно подходит для небольших дней рождения, семейных юбилеев, камерных корпоративов, деловых ужинов и поминальных трапез в спокойной приватной атмосфере без посторонних.', '[''Вместимость: до 25 человек'', ''Приватная и теплая камерная атмосфера'', ''Персональный сервис и внимание к деталям'', ''Индивидуальный расчет банкетного меню'']', '/assets/webp/hall_small_overview-BPheGfPs.webp', '[{''src'': ''/assets/webp/hall_small_overview-BPheGfPs.webp'', ''title'': ''Панорама Малого зала'', ''desc'': ''Уютный зал с хрустальной люстрой, художественными барельефами и праздничной сервировкой'', ''alt'': ''Малый банкетный зал: общая панорама, хрустальная люстра и банкетный стол''}, {''src'': ''/assets/webp/hall_small_banquet-DnvCC_qU.webp'', ''title'': ''Банкетная рассадка и декор'', ''desc'': ''Столы для компании до 25 персон, кружевные портьеры, настенное панно и мягкий свет'', ''alt'': ''Малый банкетный зал: сервировка банкетного стола и вид на панно''}, {''src'': ''/assets/webp/hall_small_mirror-CT1DIpjN.webp'', ''title'': ''Лаунж с зеркалом и ТВ'', ''desc'': ''Большое панорамное зеркало с подсветкой, экран для видеопоздравлений и приватная атмосфера'', ''alt'': ''Малый банкетный зал: банкетный стол, панорамное зеркало с подсветкой и ТВ''}, {''src'': ''/assets/webp/hall_small_mural_street-BPH5CGiP.webp'', ''title'': ''Барельеф «Итальянская улочка»'', ''desc'': ''Объёмная художественная роспись ручной работы с фактурной каменной кладкой и цветами'', ''alt'': ''Малый банкетный зал: художественный барельеф итальянской улочки''}, {''src'': ''/assets/webp/hall_small_mural_feast-B7viDVYW.webp'', ''title'': ''Панно «Королевский пир»'', ''desc'': ''Фактурная картина торжественного застолья и скульптурные элементы в кирпичном обрамлении'', ''alt'': ''Малый банкетный зал: барельеф торжественного застолья и скульптурный лев''}]', 2, 1);
