-- ==============================================================================
-- База данных для кафе «Белоснежка» MySQL (bel7916394_db)
-- Полный дамп со структурой и актуальными данными (с фото)
-- ==============================================================================

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `dishes`;
DROP TABLE IF EXISTS `category_sections`;
DROP TABLE IF EXISTS `categories`;
DROP TABLE IF EXISTS `promotions`;
DROP TABLE IF EXISTS `halls`;
DROP TABLE IF EXISTS `gallery`;
DROP TABLE IF EXISTS `bookings`;
DROP TABLE IF EXISTS `admins`;
DROP TABLE IF EXISTS `site_settings`;

-- 1. Таблица администраторов
CREATE TABLE `admins` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `role` VARCHAR(20) DEFAULT 'admin',
  `last_login` DATETIME NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Учётная запись администратора по умолчанию (BCrypt)

-- 2. Таблица категорий меню
CREATE TABLE `categories` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `category_id` VARCHAR(50) NOT NULL UNIQUE,
  `label` VARCHAR(100) NOT NULL,
  `badge` VARCHAR(50) NULL,
  `hero_img` VARCHAR(255) NULL,
  `tagline` TEXT NULL,
  `sort_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Таблица блюд меню
CREATE TABLE `dishes` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `category_ref` VARCHAR(50) NOT NULL,
  `section_id` INT DEFAULT 1,
  `section_title` VARCHAR(100) NULL,
  `name` VARCHAR(150) NOT NULL,
  `weight` VARCHAR(50) NULL,
  `price` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  `price_text` VARCHAR(50) NULL,
  `note` TEXT NULL,
  `description` TEXT NULL,
  `tag` VARCHAR(50) NULL,
  `img` VARCHAR(255) NULL,
  `is_available` TINYINT(1) DEFAULT 1,
  `sort_order` INT DEFAULT 0,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_cat` (`category_ref`),
  INDEX `idx_avail` (`is_available`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Таблица акций
CREATE TABLE `promotions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `category` VARCHAR(50) NOT NULL,
  `tag` VARCHAR(50) NULL,
  `badge` VARCHAR(50) NULL,
  `title` VARCHAR(150) NOT NULL,
  `subtitle` VARCHAR(200) NULL,
  `description` TEXT NULL,
  `bonus_label` VARCHAR(100) NULL,
  `bonus` TEXT NULL,
  `action_label` VARCHAR(100) DEFAULT 'Забронировать',
  `action_type` VARCHAR(50) DEFAULT 'table',
  `img` VARCHAR(255) NULL,
  `is_active` TINYINT(1) DEFAULT 1,
  `sort_order` INT DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. Таблица банкетных залов
CREATE TABLE `halls` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(100) NOT NULL,
  `slug` VARCHAR(50) NOT NULL UNIQUE,
  `capacity` VARCHAR(50) NULL,
  `description` TEXT NULL,
  `features` JSON NULL,
  `img` VARCHAR(255) NULL,
  `photos` JSON NULL,
  `sort_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 6. Таблица фотогалереи
CREATE TABLE `gallery` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(150) NULL,
  `category` VARCHAR(50) DEFAULT 'Интерьер',
  `img` VARCHAR(255) NOT NULL,
  `sort_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 7. Таблица бронирований и заявок
CREATE TABLE `bookings` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `type` VARCHAR(30) DEFAULT 'table',
  `name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(50) NOT NULL,
  `booking_date` VARCHAR(50) NULL,
  `booking_time` VARCHAR(50) NULL,
  `guests` VARCHAR(20) NULL,
  `hall` VARCHAR(50) NULL,
  `comment` TEXT NULL,
  `rating` INT NULL,
  `status` VARCHAR(30) DEFAULT 'new',
  `source` VARCHAR(50) DEFAULT 'website',
  `vk_sent` TINYINT(1) DEFAULT 0,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 8. Таблица настроек сайта
CREATE TABLE `site_settings` (
  `setting_key` VARCHAR(50) PRIMARY KEY,
  `setting_value` TEXT NULL,
  `description` VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;